def solve_example():
    # Simple AP: t_i = i. N=4, L=3.
    T = [0, 1, 2, 3]

    # Calculate S = {t_i + t_j | 0 <= i <= j < N}
    S = set()
    for i in range(len(T)):
        for j in range(i, len(T)):
            S.add(T[i] + T[j])

    # Calculate D = {t_j - t_i | 0 <= i < j < N}
    D = set()
    for i in range(len(T)):
        for j in range(i + 1, len(T)):
            D.add(T[j] - T[i])

    print(f"T = {T}")
    print(f"|D| = {len(D)}")
    print(f"|S| = {len(S)}")
    print(f"Relationship check: 2*|D| + 1 = {2*len(D) + 1}")

solve_example()

def calculate_sumset_size(T):
    S = set()
    n = len(T)
    for i in range(n):
        for j in range(i, n):
            S.add(T[i] + T[j])
    return len(S)

